#include  "x86_64.H"
#include  "x86_64_isa.cpp"

#include  "x86_64_syscall.H"

void* x86_64::dispatch() {
  if( ac_pc >= dec_cache_size){
    cerr << "ArchC: Address out of bounds (pc=0x" << hex << ac_pc << ")." << endl;
    stop();
    longjmp(ac_env, AC_ACTION_STOP);
  }
  ac_instr_counter++;
  unsigned ins_id;
  instr_dec = (DEC_CACHE + (ac_pc / 4));
  if ( !instr_dec->valid ){
    unsigned* ins_cache;
    decode_pc = ac_pc;
    quant = 0;
    ins_cache = (ISA.decoder)->Decode(reinterpret_cast<unsigned char*>(buffer), quant);
    instr_dec->valid = true;
    instr_dec->id = ins_cache ? ins_cache[IDENT]: 0;
    instr_dec->end_rot = IntRoutine[instr_dec->id];
    switch (ISA.instr_format_table[instr_dec->id]) {
      case 1:
        instr_dec->F_Type_RR.opcode = ins_cache[1];
        instr_dec->F_Type_RR.rex = ins_cache[2];
        instr_dec->F_Type_RR.reg = ins_cache[3];
        instr_dec->F_Type_RR.rm = ins_cache[4];
        instr_dec->F_Type_RR.pad = ins_cache[5];
      break;
      case 2:
        instr_dec->F_Type_RI.opcode = ins_cache[1];
        instr_dec->F_Type_RI.reg = ins_cache[2];
        instr_dec->F_Type_RI.pad = ins_cache[3];
        instr_dec->F_Type_RI.imm = ins_cache[6];
      break;
      case 3:
        instr_dec->F_Type_RM.opcode = ins_cache[1];
        instr_dec->F_Type_RM.reg = ins_cache[2];
        instr_dec->F_Type_RM.rm = ins_cache[3];
        instr_dec->F_Type_RM.disp = ins_cache[6];
      break;
      case 4:
        instr_dec->F_Type_J.opcode = ins_cache[1];
        instr_dec->F_Type_J.offset = ins_cache[7];
      break;
      case 5:
        instr_dec->F_Type_HLT.opcode = ins_cache[1];
        instr_dec->F_Type_HLT.pad = ins_cache[8];
      break;
      default:
        cerr << "ArchC Error: Unidentified instruction. " << endl;
        cerr << "PC = " << hex << ac_pc << dec << endl;
        stop();
        longjmp(ac_env, AC_ACTION_STOP);
    }
  }
  ins_id = instr_dec->id;

  return instr_dec->end_rot;
}

